-- Administrator-published momentum screen. Public reads go through the backend.
create table if not exists public.manual_momentum_screener_snapshots (
  id bigint generated always as identity primary key,
  as_of date not null,
  created_at timestamptz not null default now(),
  row_count integer not null check (row_count > 0 and row_count <= 5000),
  rows jsonb not null check (jsonb_typeof(rows) = 'array' and jsonb_array_length(rows) = row_count),
  published_by uuid
);

create index if not exists manual_momentum_screener_snapshots_latest_idx
  on public.manual_momentum_screener_snapshots (id desc);

alter table public.manual_momentum_screener_snapshots enable row level security;
revoke all on public.manual_momentum_screener_snapshots from anon, authenticated;
revoke all on sequence public.manual_momentum_screener_snapshots_id_seq from anon, authenticated;


